import { cn } from "@/lib/utils"
import { format } from "./i18n.ts"
import type { FieldMeta } from "./meta.ts"

/** The dot of each color. */
const DOTS: Record<string, string> = {
  green: "bg-success",
  amber: "bg-warning",
  red: "bg-destructive",
  blue: "bg-primary",
  violet: "bg-violet-500",
  sky: "bg-sky-500",
  orange: "bg-orange-500",
  gray: "bg-neutral-400 dark:bg-neutral-500",
}

/** The dot of a value of an enum field, in its color. */
export function StatusDot({ field, value, className }: { field: FieldMeta; value: unknown; className?: string }) {
  const color = field.colors?.[String(value)] ?? "gray"
  return <span aria-hidden className={cn("size-2 shrink-0 rounded-full", DOTS[color] ?? DOTS.gray, className)} />
}

/** A value of an enum field: its dot and its label. */
export function StatusValue({ field, value }: { field: FieldMeta; value: unknown }) {
  return (
    <span className="inline-flex items-center gap-2 font-semibold whitespace-nowrap text-foreground">
      <StatusDot field={field} value={value} />
      {format(field, value)}
    </span>
  )
}
